def unnamed_custom_function(context = {}, keys = {}, **kwargs):
	import json
	from datetime import datetime

	dtime = datetime.now().strftime("%Y_%m_%d_%H:%M:%S")

	fname = context['file_path'].split('/')[-1]
	fname = fname.split('__')
	fname = fname[0] if len(fname) == 1 else fname[1]

	required_columns = ["CVE", "Likelihood", "Scan_Source_UID", "Solution", "Title"]

	res = [
	  {"Item": "Header Row#", "Value": ""},
	  {"Item": "Sheet Name", "Value": ""}
	]
	for col in required_columns:
	  res.append({"Item": f'{col} Column', "Value": ""})
	res.append({"Item": 'Extraction ID', "Value": f"BNYM_{dtime}_{fname}"})

	try:
	  sheet_info = json.loads(context['document_text'])[0]
	  res[1]["Value"] = sheet_info["name"]

	  table = sheet_info["table"][:10]
	  header = None
	  header_index = None
	  indices = []
	  for i, row in enumerate(table):
	    for col in required_columns:
	      try:
	        indices.append(row.index(col))
	      except ValueError:
	        indices = []
	        break

	    if len(indices) == len(required_columns):
	      header = row
	      header_index = i
	      break

	  if header:
	    res[0]["Value"] = header_index + 1
	    for i, idx in enumerate(indices):
	      res[i + 2]["Value"] = header[idx]
	  else:
	    fail = 1 / 0
	except:
	  for reset in res:
	    reset["Value"] = ""

	return res

